document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("roof-pitch-form"),t=document.getElementById("roof-pitch-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("roof-rise").value),o=parseFloat(document.getElementById("roof-run").value),a=parseFloat(document.getElementById("roof-length").value),s=parseFloat(document.getElementById("roof-width").value),i=document.getElementById("roof-style").value,[r,l]=document.getElementById("roof-material").value.split(",");if(n<0||o<=0||a<=0||s<=0)return t.textContent="Please enter valid measurements.",void 0;const p=n/o*12,d=`${p.toFixed(1)}/12`,c=Math.atan(n/o)*(180/Math.PI),m=Math.sqrt(1+Math.pow(n/o,2)),h=a*s;let u;switch(i){case"gable":case"shed":default:u=h*m;break;case"hip":u=h*m*1.1;break;case"gambrel":u=h*m*1.15}const f=u/100;let g,$,v;p<2?(g="Flat roof",$="Membrane or metal only"):p<4?(g="Low slope",$="Metal roofing or special shingle installation"):p<9?(g="Conventional slope",$="All roofing materials suitable"):p<21?(g="Steep slope",$="All materials, may need snow guards"):(g="Very steep",$="Specialized installation required"),v=p<=6?"Walkable with proper footwear":p<=9?"Requires safety equipment":"Professional installation recommended";const y=Math.sqrt(Math.pow(s/2,2)+Math.pow(s/2*(n/o),2)),b=f*parseFloat(l),F=50*f,w=2*(a+s)*8,M=150*Math.ceil(u/300),x=b+F+w+M,q=8*f*(p>8?1.5:1),C=75*q;let E;switch(i){case"gable":default:E=.1;break;case"hip":E=.15;break;case"shed":E=.05;break;case"gambrel":E=.2}const I=f*(1+E);t.innerHTML=`\n        <div class="result-section">\n          <h4>Roof Pitch Calculations:</h4>\n          <p><strong>Pitch ratio: ${d}</strong></p>\n          <p><strong>Angle: ${c.toFixed(1)}°</strong></p>\n          <p>Slope classification: ${g}</p>\n          <p>Roof factor: ${m.toFixed(3)}</p>\n        </div>\n        \n        <div class="result-measurements">\n          <h4>Roof Measurements:</h4>\n          <p>Building: ${a}' × ${s}' (${h} sq ft floor)</p>\n          <p>Roof style: ${i.charAt(0).toUpperCase()+i.slice(1)}</p>\n          <p><strong>Roof area: ${u.toFixed(0)} sq ft</strong></p>\n          <p><strong>Roofing squares: ${f.toFixed(1)}</strong></p>\n          <p>Rafter length: ${y.toFixed(1)}' (gable roof)</p>\n        </div>\n        \n        <div class="result-suitability">\n          <h4>Material Suitability:</h4>\n          <p><strong>${$}</strong></p>\n          <p>Safety level: ${v}</p>\n          ${p<4&&"asphalt"===r?"<p>⚠️ Special installation techniques required for asphalt shingles</p>":""}\n          ${p>9?"<p>💡 Consider snow guards in snow-prone areas</p>":""}\n        </div>\n        \n        <div class="result-materials">\n          <h4>Material Estimates:</h4>\n          <p>Base requirement: ${f.toFixed(1)} squares</p>\n          <p>With ${100*E}% waste: ${I.toFixed(1)} squares</p>\n          <p>${r.charAt(0).toUpperCase()+r.slice(1)}: $${b.toFixed(0)}</p>\n          <p>Underlayment: $${F.toFixed(0)}</p>\n          <p>Flashing: $${w.toFixed(0)}</p>\n          <p>Ventilation: $${M.toFixed(0)}</p>\n          <p><strong>Total materials: $${x.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Details:</h4>\n          <p>Labor hours: ${q.toFixed(1)} hours</p>\n          <p>Professional labor: $${C.toFixed(0)}</p>\n          <p><strong>Total project: $${(x+C).toFixed(0)}</strong></p>\n          <p>Installation time: ${Math.ceil(q/16)} days (2-person crew)</p>\n        </div>\n        \n        <div class="result-drainage">\n          <h4>Drainage Performance:</h4>\n          ${p>=4?"<p>✅ Excellent water shedding</p>":"<p>⚠️ May require additional drainage considerations</p>"}\n          ${p>=6?"<p>✅ Good snow shedding capability</p>":"<p>💡 Snow retention may be an issue</p>"}\n          <p>Gutters recommended: ${p>=3?"Yes":"Essential"}</p>\n        </div>\n        \n        <div class="result-comparison">\n          <h4>Common Pitch Comparisons:</h4>\n          <p>4/12 (18.5°): Standard minimum for shingles</p>\n          <p>6/12 (26.5°): Most common residential pitch</p>\n          <p>8/12 (33.7°): Traditional steep residential</p>\n          <p>12/12 (45°): Very steep, A-frame style</p>\n          <p><strong>Your pitch: ${d} (${c.toFixed(1)}°)</strong></p>\n        </div>\n        \n        <div class="result-climate">\n          <h4>Climate Recommendations:</h4>\n          ${p>=6?"<p>✅ Suitable for heavy snow areas</p>":"<p>⚠️ Consider steeper pitch for heavy snow</p>"}\n          ${p>=4&&p<=8?"<p>✅ Good for high wind areas</p>":"<p>💡 Moderate pitches perform best in high winds</p>"}\n          ${p>=4?"<p>✅ Adequate for heavy rain areas</p>":"<p>⚠️ May need special waterproofing</p>"}\n        </div>\n        \n        <div class="result-tips">\n          <h4>Professional Recommendations:</h4>\n          <p>🏠 Consider attic space vs. pitch trade-offs</p>\n          <p>💰 Steeper roofs cost more but may last longer</p>\n          <p>🌡️ Account for local climate in pitch selection</p>\n          <p>📋 Check local building codes for minimum requirements</p>\n          <p>🔧 Professional installation recommended for slopes over 9/12</p>\n        </div>\n      `})});